// Types of the packed data files under public/data/ and the loaders the page
// uses. The files are generated by scripts/table-extract.mjs and
// scripts/pack-v5.mjs; nothing here computes a number.
import type { Colour, State, Triple } from './engine';

/** From the view of the player who chose the move; `plies` counts that move. */
export type Verdict = { kind: 'keeps-draw' } | { kind: 'wins-in' | 'loses-in'; plies: number };

export interface VerdictMove {
  move: Triple;
  verdict: Verdict;
}

/**
 * One step of the retrograde-analysis figure. `to` indexes the `positions` of
 * the step before it (won-1 points into lost-0, lost-2 into won-1).
 */
export interface RetroStep {
  label: 'lost-0' | 'won-1' | 'lost-2';
  positions: { state: State; moves?: { move: Triple; to: number }[] }[];
}

export interface TableData {
  game: 'A';
  /** The table file and the tool that read it. */
  source: string;
  openings: VerdictMove[];
  /** Keyed by the opening's move name; every legal reply of the other side. */
  replies: Record<string, VerdictMove[]>;
  retro: RetroStep[];
  lines: { shortestWin: Triple[]; loop: Triple[]; centreLoss: Triple[]; openingWin: Triple[] };
}

export interface Score {
  score: number;
  ci95: [number, number];
}

export type Program = 'qtab' | 'td' | 'az100' | 'az0';

export interface V5Stage extends Score {
  pct: number;
  gamesTrained: number;
  /** The seed-1 bench against greedy and the game it kept, as repo-relative paths. */
  source: { bench: string; game: string };
  game: Triple[];
  playerColour: Colour;
  result: 'win' | 'loss';
}

export interface V5Mosaic {
  pct: number;
  source: string;
  games: { result: 'win' | 'loss'; mistakes: number; judged: number }[];
}

export interface V5Data {
  rules: 'lc1-2';
  opponent: 'greedy';
  seed: 1;
  source: string;
  stagesPct: number[];
  /** Each entry is that player's score against the greedy player under lc1-2; `table` is the perfect-play player's measured score, not the game-A solved value. */
  references: Record<'random' | 'greedy' | 'table', Score>;
  programs: Record<Program, { label: string; stages: V5Stage[] }>;
  mosaics: Record<'qtab' | 'td' | 'az100', V5Mosaic[]>;
}

export interface ReachData {
  positionsTotal: number;
  reachable: number;
  /** Positions first met at ply 0, 1, … 15. */
  firstSeenAtPly: number[];
  source: string;
}

async function loadJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`pogo-figures: could not fetch ${url} (${response.status})`);
  }
  return (await response.json()) as T;
}

export const loadTable = (url: string): Promise<TableData> => loadJson<TableData>(url);
export const loadV5 = (url: string): Promise<V5Data> => loadJson<V5Data>(url);
export const loadReach = (url: string): Promise<ReachData> => loadJson<ReachData>(url);
